<?php require '_layout.php';$db=db();$ST=['new','confirmed','preparing','ready','out','completed','cancelled'];
if(isset($_POST['payment_status'])){$id=(int)($_POST['id']??0);$status=$_POST['payment_status'];if(in_array($status,['unpaid','verified','failed'],true)){$db->prepare("UPDATE orders SET payment_status=? WHERE id=? AND payment='transfer'")->execute([$status,$id]);header('Location: orders.php?id='.$id.'&payment=1');exit;}}
if(isset($_POST['refund_status'])){$id=(int)($_POST['id']??0);$status=$_POST['refund_status'];$amount=round(max(0,(float)($_POST['refund_amount']??0)),2);$note=mb_substr(trim((string)($_POST['refund_note']??'')),0,500);if(in_array($status,['none','requested','processing','completed','rejected'],true)){$s=$db->prepare('SELECT total FROM orders WHERE id=?');$s->execute([$id]);$total=$s->fetchColumn();if($total!==false&&$amount<=(float)$total&&($status!=='completed'||$amount>0)){$db->prepare('UPDATE orders SET refund_status=?,refund_amount=?,refund_note=?,refunded_at=? WHERE id=?')->execute([$status,$amount,$note?:null,$status==='completed'?date('Y-m-d H:i:s'):null,$id]);header('Location: orders.php?id='.$id.'&refund=1');exit;}}header('Location: orders.php?id='.$id.'&error='.urlencode('Enter a refund amount no higher than the order total; completed refunds need an amount above zero.'));exit;}
if(isset($_POST['status'])&&in_array($_POST['status'],$ST)){$id=(int)($_POST['id']??0);$next=$_POST['status'];$db->beginTransaction();try{$s=$db->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetchColumn();if($old===false)throw new RuntimeException('Order not found.');
 if($old!=='cancelled'&&$next==='cancelled'){$it=$db->prepare('SELECT sku,qty FROM order_items WHERE order_id=?');$it->execute([$id]);foreach($it as $line)$db->prepare('UPDATE products SET stock=stock+? WHERE sku=?')->execute([(int)ceil((float)$line['qty']),$line['sku']]);}
 elseif($old==='cancelled'&&$next!=='cancelled'){$it=$db->prepare('SELECT sku,qty FROM order_items WHERE order_id=?');$it->execute([$id]);foreach($it as $line){$qty=(int)ceil((float)$line['qty']);$p=$db->prepare('SELECT stock FROM products WHERE sku=? FOR UPDATE');$p->execute([$line['sku']]);$stock=$p->fetchColumn();if($stock===false||(int)$stock<$qty)throw new RuntimeException('Stock is too low to reopen this cancelled order. Restock the products first.');$db->prepare('UPDATE products SET stock=stock-? WHERE sku=?')->execute([$qty,$line['sku']]);}}
 $db->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$next,$id]);$db->commit();header('Location: orders.php?id='.$id.'&ok=1');exit;
 }catch(Throwable $x){if($db->inTransaction())$db->rollBack();$msg=$x->getMessage();header('Location: orders.php?id='.$id.'&error='.urlencode($msg));exit;}}
