 if($o){$it=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$o['id']]);$it=$it->fetchAll();$ph=preg_replace('/\D/','',$o['phone']);if($ph[0]=='0')$ph='44'.substr($ph,1);
