ahead('Orders','orders.php');$f=$_GET['s']??'';$q=trim($_GET['q']??'');$payfilter=$_GET['pay']??'';$w=['1=1'];$a=[];if(in_array($f,$ST)){$w[]='status=?';$a[]=$f;}if($payfilter==='clicked')$w[]="payment_status='customer_marked_paid'";if($payfilter==='awaiting')$w[]="payment='transfer' AND payment_status='unpaid'";if($q!==''){$w[]='(ref LIKE ? OR name LIKE ? OR phone LIKE ?)';array_push($a,"%$q%","%$q%","%$q%");}$pg=max(1,(int)($_GET['p']??1));$per=50;$count=$db->prepare('SELECT COUNT(*) FROM orders WHERE '.implode(' AND ',$w));$count->execute($a);$total=(int)$count->fetchColumn();
